SELECT sc.id, sc.check_no, sc.warehouse_id, w.name AS warehouse_name,
       sc.status, sc.remark, sc.operator_id, sc.operator_name,
       sc.created_at, sc.updated_at
FROM stock_check sc
LEFT JOIN warehouse w ON w.id = sc.warehouse_id AND w.deleted = 0
WHERE sc.deleted = 0

    AND sc.warehouse_id = #{warehouseId}


    AND sc.status = #{status}

ORDER BY sc.created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM stock_check
WHERE deleted = 0

    AND warehouse_id = #{warehouseId}


    AND status = #{status}
